const safe={top:0,right:0,bottom:0,left:0};export function createLocalPlatform(){let state=null,over=false;try{state=JSON.parse(localStorage.getItem('gamelab-polyrace-state')||'null');}catch{}const info={viewContext:'full_screen',contentSafeAreaInset:safe,initialGameState:state==null?null:{gameState:state}};return {get info(){return info},get safeArea(){return safe},get state(){return state},get isOver(){return over},ready:async()=>info,rearm(){over=false},gameOver(){over=true},saveState(next){localStorage.setItem('gamelab-polyrace-state',JSON.stringify(next));state=next},attachAudio(adapter){adapter.apply({master:1,muted:false,music:1,sfx:1});return ()=>{}},onPlayAgain(){return ()=>{}},onGameInfo(cb){cb(info);return ()=>{}},reportError(error){console.error(error)}};}